class Solution {
public:
    int longestSubsequence(vector<int>& arr, int difference) {
        int dp[40001] = {0};
        const int offset = 20000;
        int ans = 0;
        for (int v : arr) {
            int prev = v - difference;
            int val = 1 + dp[prev + offset];
            int idx = v + offset;
            if (val > dp[idx]) dp[idx] = val;
            if (val > ans) ans = val;
        }
        return ans;
    }
};
